INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist .aiff immer komprimiert?', 2, '[{"text": "Nein", "correct": true, "because": "Unkomprimiertes Audioformat"}, {"text": "Ja", "correct": false, "because": "Nicht wie MP3"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Format nutze ich für unkomprimiertes Audio?', 3, '[{"text": ".aiff", "correct": true, "because": "Speichert Rohdaten"}, {"text": ".avi", "correct": false, "because": "Videoformat"}, {"text": ".bmp", "correct": false, "because": "Bildformat"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften hat .avi?', 5, '[{"text": "Containerformat", "correct": true, "because": "Kombiniert Audio/Video"}, {"text": "Verschiedene Codecs", "correct": true, "because": "Flexibel einsetzbar"}, {"text": "Nur Audio", "correct": false, "because": "Auch Video"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) .bmp ist verlustfrei. b) .avi ist immer klein.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "AVI-Größe hängt vom Codec ab"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Wahl eines Videoformats?', 4, '[{"text": "Codec-Unterstützung", "correct": false, "because": "Entscheidend für .avi"}, {"text": "Dateigröße", "correct": false, "because": "Wichtig für Speicher"}, {"text": "Dateiname", "correct": true, "because": "Irrelevant für Format"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob .aif und .aiff identisch sind?', 2, '[{"text": "Ja", "correct": true, "because": "Nur Schreibvarianten"}, {"text": "Nein", "correct": false, "because": "Gleiches Format"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Format ist für Bitmap-Bilder gedacht?', 3, '[{"text": ".bmp", "correct": true, "because": "Speichert Pixel direkt"}, {"text": ".avi", "correct": false, "because": "Videoformat"}, {"text": ".aiff", "correct": false, "because": "Audioformat"}]'),
('00000000-0000-0000-0000-000000000000', 'Was gehört zu .avi?', 5, '[{"text": "Audio/Video-Daten", "correct": true, "because": "Container für beides"}, {"text": "Codec-Flexibilität", "correct": true, "because": "Unterschiedliche Kompression"}, {"text": "Verlustfreie Bilder", "correct": false, "because": "Nicht wie .bmp"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) .bmp ist groß. b) .aiff ist nur für Windows. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "AIFF ist plattformunabhängig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei einem Audioformat unwichtig?', 4, '[{"text": "Sample-Rate", "correct": false, "because": "Definiert Qualität"}, {"text": "Bit-Tiefe", "correct": false, "because": "Wichtig für .aiff"}, {"text": "Bildauflösung", "correct": true, "because": "Nur für Bilder relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist .avi verlustfrei?', 2, '[{"text": "Nein", "correct": true, "because": "Hängt vom Codec ab"}, {"text": "Ja", "correct": false, "because": "Nicht standardmäßig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile hat .bmp?', 4, '[{"text": "Keine Kompression", "correct": true, "because": "Verlustfrei"}, {"text": "Einfache Struktur", "correct": true, "because": "Direkte Pixelzuordnung"}, {"text": "Kleine Dateien", "correct": false, "because": "Oft groß"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass .aiff besser als .wav ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Beide sind verlustfrei, nur Plattformunterschied"}, {"text": "Ja", "correct": false, "because": "Kein qualitativer Vorteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei einem Bildformat?', 3, '[{"text": "Qualität", "correct": true, "because": "Verlustfrei wie .bmp"}, {"text": "Kompatibilität", "correct": false, "because": "Sekundär"}, {"text": "Schnellspeicherung", "correct": false, "because": "Weniger relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) .avi unterstützt mehrere Streams. b) .bmp ist komprimiert.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "BMP ist unkomprimiert"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachteile hat .bmp?', 5, '[{"text": "Große Dateigröße", "correct": true, "because": "Keine Kompression"}, {"text": "Eingeschränkte Farbtiefe", "correct": false, "because": "Unterstützt bis 32-Bit"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei einem Videoformat unwichtig?', 3, '[{"text": "Auflösung", "correct": false, "because": "Definiert Qualität"}, {"text": "Codec", "correct": false, "because": "Entscheidend für .avi"}, {"text": "Bit-Tiefe Audio", "correct": true, "because": "Nur Audio relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Unterstützt .aiff Metadaten?', 3, '[{"text": "Ja", "correct": true, "because": "Kann Tags speichern"}, {"text": "Nein", "correct": false, "because": "Eingeschränkt, aber möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob .avi für moderne Anwendungen optimal ist?', 2, '[{"text": "Nein", "correct": true, "because": "Veraltet gegenüber MP4"}, {"text": "Ja", "correct": false, "because": "Weniger effizient"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Format wähle ich für einfache Grafiken?', 4, '[{"text": ".bmp", "correct": true, "because": "Verlustfrei und simpel"}, {"text": ".avi", "correct": false, "because": "Videoformat"}, {"text": ".aiff", "correct": false, "because": "Audioformat"}]');
